-- =====================================================================
-- Fortress Job Book Tracker — core schema
-- Two book types (flowline | facility) share one schema. The section
-- template is data-driven: a new book type is configuration, not a
-- migration.
-- =====================================================================

create extension if not exists "pgcrypto";
create extension if not exists "citext";

-- ---------------------------------------------------------------------
-- Controlled vocabularies. These exist as enums specifically because the
-- source data proves free text does not survive contact with the field
-- ("ASME XI" for "ASME IX", four spellings of one welder's name).
-- ---------------------------------------------------------------------
create type book_type          as enum ('flowline', 'facility');
create type job_book_status    as enum ('setup','in_progress','ready_for_review','submitted','accepted','archived');
create type section_status     as enum ('not_started','in_progress','ready_for_review','approved','na');
create type requirement_type   as enum ('document','personnel_certs','equipment_certs','records','derived','supplemental');
create type user_role          as enum ('fortress_admin','qaqc_manager','qaqc_tech','fortress_read_only','client_user','third_party_inspector');
create type applies_to         as enum ('flowline','facility','both');
create type ndt_method         as enum ('RT','PT','MT','UT');
create type pass_fail          as enum ('Pass','Fail');
create type weld_status        as enum ('planned','welded','visual_complete','ndt_complete','not_used','cut_out');
create type joint_type         as enum ('Butt','O-let','Socket','Branch');
create type qualification_code as enum ('ASME_IX','API_1104');
create type mtr_status         as enum ('on_file','missing','illegible','unidentified');
create type doc_visibility     as enum ('internal','client','inspector');
create type flag_severity      as enum ('critical','warning','info');
create type flag_state         as enum ('open','acknowledged','resolved','dismissed');
create type cert_subject_type  as enum ('welder','cwi','ndt_technician','torque_wrench','pressure_recorder');

-- ---------------------------------------------------------------------
-- Organizations, users, access
-- ---------------------------------------------------------------------
create table client_org (
  id          uuid primary key default gen_random_uuid(),
  name        text not null unique,
  logo_url    text,
  created_at  timestamptz not null default now(),
  deleted_at  timestamptz
);

create table app_user (
  id            uuid primary key default gen_random_uuid(),
  auth_user_id  uuid unique,                    -- maps to auth.users.id
  email         citext not null unique,
  full_name     text not null,
  role          user_role not null,
  client_org_id uuid references client_org(id),
  sso_subject   text,
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  deleted_at    timestamptz,
  -- A client user is meaningless without an org; a Fortress user must not
  -- carry one, or client isolation would leak in both directions.
  constraint client_user_has_org check (
    (role = 'client_user' and client_org_id is not null)
    or (role <> 'client_user' and (client_org_id is null or role = 'third_party_inspector'))
  )
);

create table project (
  id               uuid primary key default gen_random_uuid(),
  client_org_id    uuid not null references client_org(id),
  name             text not null,
  operator_pic_name text,
  afe_number       text,
  created_at       timestamptz not null default now(),
  deleted_at       timestamptz
);

create table job_book (
  id                    uuid primary key default gen_random_uuid(),
  project_id            uuid not null references project(id),
  book_template_id      uuid not null,          -- fk added after book_template
  book_type             book_type not null,
  job_number            text not null,
  facility_name         text,
  drill_pad_name        text,
  well_names            text[] not null default '{}',
  construction_company  text,
  welding_company       text,
  cwi_names             text[] not null default '{}',
  pipe_size_in          text,
  pipe_schedule         text,
  pipe_grade            text,
  status                job_book_status not null default 'setup',
  target_turnover_date  date,
  -- Construction window. Reports and records dated outside it are flagged.
  construction_start    date,
  construction_end      date,
  -- The as-of date the field logs were closed against. Records dated after
  -- this are "future-dated" relative to the log itself — the single most
  -- common transcription error in these books.
  data_as_of_date       date,
  -- Per-job compliance thresholds. These are operator-spec driven, never
  -- hard-coded.
  required_xray_pct         numeric(5,2) not null default 10.00,
  required_torque_inspect_pct numeric(5,2) not null default 10.00,
  torque_tolerance_pct      numeric(5,2) not null default 5.00,
  cert_expiry_warning_days  integer not null default 60,
  -- Which welder on a split-pass joint receives X-ray credit.
  xray_credit_rule      text not null default 'all_passes' check (
    xray_credit_rule in ('all_passes','root_welder','cap_welder')
  ),
  created_by            uuid references app_user(id),
  created_at            timestamptz not null default now(),
  deleted_at            timestamptz,
  unique (project_id, job_number)
);

create table job_assignment (
  job_book_id   uuid not null references job_book(id) on delete cascade,
  user_id       uuid not null references app_user(id),
  assigned_role text not null,
  assigned_at   timestamptz not null default now(),
  primary key (job_book_id, user_id)
);

create table inspector_grant (
  id          uuid primary key default gen_random_uuid(),
  job_book_id uuid not null references job_book(id) on delete cascade,
  user_id     uuid not null references app_user(id),
  expires_at  timestamptz,
  can_comment boolean not null default false,
  granted_by  uuid references app_user(id),
  granted_at  timestamptz not null default now(),
  revoked_at  timestamptz,
  unique (job_book_id, user_id)
);

-- ---------------------------------------------------------------------
-- Section templates. Versioned so historical scores stay reproducible.
-- ---------------------------------------------------------------------
create table book_template (
  id             uuid primary key default gen_random_uuid(),
  book_type      book_type not null,
  version        integer not null,
  effective_date date not null,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  unique (book_type, version)
);

alter table job_book
  add constraint job_book_template_fk
  foreign key (book_template_id) references book_template(id);

create table section_definition (
  id                 uuid primary key default gen_random_uuid(),
  book_template_id   uuid not null references book_template(id) on delete cascade,
  section_number     text not null,             -- text: flowline uses "19-22"
  sort_order         integer not null,
  title              text not null,             -- verbatim from the checklist
  applies_to         applies_to not null default 'both',
  weight             numeric(6,2) not null default 0,
  requirement_type   requirement_type not null,
  min_documents      integer not null default 1,
  linked_record_type text,
  is_required        boolean not null default true,
  -- Supplemental sections (e.g. the Flexpipe DFRs delivered in DP452 that
  -- appear nowhere on the checklist) carry weight 0 and never distort the
  -- percentage.
  is_supplemental    boolean not null default false,
  notes              text,
  unique (book_template_id, section_number)
);

create table job_book_section (
  id                    uuid primary key default gen_random_uuid(),
  job_book_id           uuid not null references job_book(id) on delete cascade,
  section_definition_id uuid not null references section_definition(id),
  status                section_status not null default 'not_started',
  na_reason             text,
  ready_for_review_by   uuid references app_user(id),
  ready_for_review_at   timestamptz,
  approved_by           uuid references app_user(id),
  approved_at           timestamptz,
  computed_pct          numeric(5,2) not null default 0,
  internal_notes        text,                   -- never exposed to clients
  unique (job_book_id, section_definition_id),
  -- Two-person control: approval must be recorded with an approver, and the
  -- approver may not be the tech who marked it ready. Enforced again in the
  -- approve_section() function.
  constraint approval_is_attributed check (
    (status <> 'approved') or (approved_by is not null and approved_at is not null)
  ),
  constraint approver_is_not_submitter check (
    approved_by is null or ready_for_review_by is null or approved_by <> ready_for_review_by
  )
);

-- ---------------------------------------------------------------------
-- Documents
-- ---------------------------------------------------------------------
create table document (
  id                     uuid primary key default gen_random_uuid(),
  job_book_id            uuid not null references job_book(id) on delete cascade,
  section_id             uuid references job_book_section(id),
  record_type            text,                  -- polymorphic attachment target
  record_id              uuid,
  original_filename      text not null,
  normalized_filename    text not null,
  storage_path           text not null,
  mime_type              text,
  byte_size              bigint,
  sha256                 text not null,
  page_count             integer,
  version                integer not null default 1,
  supersedes_document_id uuid references document(id),
  is_superseded          boolean not null default false,
  visibility             doc_visibility not null default 'internal',
  uploaded_by            uuid references app_user(id),
  uploaded_at            timestamptz not null default now(),
  approved_by            uuid references app_user(id),
  approved_at            timestamptz,
  -- Soft delete only. Nothing in a compliance record is ever destroyed.
  deleted_at             timestamptz,
  deleted_by             uuid references app_user(id),
  delete_reason          text
);
create index document_book_idx    on document(job_book_id) where deleted_at is null;
create index document_section_idx on document(section_id)  where deleted_at is null;
create index document_sha_idx     on document(job_book_id, sha256);
create index document_record_idx  on document(record_type, record_id);

-- ---------------------------------------------------------------------
-- Personnel and equipment
-- ---------------------------------------------------------------------
create table welder (
  id          uuid primary key default gen_random_uuid(),
  full_name   text not null,
  initials    text not null,
  employer    text,
  active      boolean not null default true,
  -- The source data carries four spellings of one man's name. Welders are a
  -- managed entity keyed by initials + qualification record; the misspellings
  -- live here as aliases so imports resolve to one person.
  name_aliases text[] not null default '{}',
  created_at  timestamptz not null default now(),
  deleted_at  timestamptz,
  unique (initials)
);

create table welder_qualification (
  id                      uuid primary key default gen_random_uuid(),
  welder_id               uuid not null references welder(id) on delete cascade,
  code                    qualification_code not null,
  process                 text,
  qualification_date      date not null,
  expiry_date             date,
  continuity_last_verified date,
  document_id             uuid references document(id),
  created_at              timestamptz not null default now(),
  deleted_at              timestamptz
);

create table cwi (
  id         uuid primary key default gen_random_uuid(),
  full_name  text not null,
  initials   text not null,
  employer   text,
  active     boolean not null default true,
  created_at timestamptz not null default now(),
  deleted_at timestamptz
);

create table ndt_technician (
  id             uuid primary key default gen_random_uuid(),
  full_name      text not null,
  initials       text,
  employer       text,
  classification text,                          -- Formal | VAR | PQC
  active         boolean not null default true,
  created_at     timestamptz not null default now(),
  deleted_at     timestamptz
);

create table torque_wrench (
  id                   uuid primary key default gen_random_uuid(),
  wrench_id            text not null,
  capacity_ft_lb       numeric(10,2),
  last_calibration_date date,
  calibration_due_date  date,
  cert_document_id     uuid references document(id),
  cert_on_file         boolean not null default false,
  -- Present in the log's roster header block, as opposed to merely used.
  on_roster            boolean not null default false,
  created_at           timestamptz not null default now(),
  deleted_at           timestamptz,
  unique (wrench_id)
);

-- One shape for every certificate. Validity is always evaluated against the
-- date the work was performed, never merely against today.
create table certificate (
  id           uuid primary key default gen_random_uuid(),
  job_book_id  uuid references job_book(id) on delete cascade,
  subject_type cert_subject_type not null,
  subject_id   uuid not null,
  cert_type    text not null,
  issuing_body text,
  issue_date   date not null,
  expiry_date  date,
  document_id  uuid references document(id),
  verified_by  uuid references app_user(id),
  verified_at  timestamptz,
  created_at   timestamptz not null default now(),
  deleted_at   timestamptz
);
create index certificate_subject_idx on certificate(subject_type, subject_id);

-- ---------------------------------------------------------------------
-- Weld records — the heaviest entity
-- ---------------------------------------------------------------------
create table weld_line (
  id               uuid primary key default gen_random_uuid(),
  job_book_id      uuid not null references job_book(id) on delete cascade,
  line_code        text not null,               -- FL1..FL25, FWT, MMB, A-1..G-1
  line_description text,
  workbook         text,                        -- 'Flow Lines' | 'Gas Lift'
  well_name        text,
  drill_pad_name   text,
  facility_name    text,
  operator_pic     text,
  welding_company  text,
  pipe_size        text,
  pipe_schedule    text,
  pipe_grade       text,
  service_type     text,
  sort_order       integer not null default 0,
  created_at       timestamptz not null default now(),
  deleted_at       timestamptz,
  unique (job_book_id, line_code)
);

create table weld (
  id                     uuid primary key default gen_random_uuid(),
  weld_line_id           uuid not null references weld_line(id) on delete cascade,
  job_book_id            uuid not null references job_book(id) on delete cascade,
  weld_number            text not null,         -- text: "NP-2" repairs exist
  sort_order             integer not null default 0,
  weld_date              date,
  welder_pass_assignment text,                  -- "HS2/HS2/CT/CT" Root/Hot/Fill/Cap
  root_welder_id         uuid references welder(id),
  hot_welder_id          uuid references welder(id),
  fill_welder_id         uuid references welder(id),
  cap_welder_id          uuid references welder(id),
  joint_type             joint_type,
  component_description  text,
  part_length            text,
  heat_numbers           text[] not null default '{}',
  cwi_initials           text,
  cwi_id                 uuid references cwi(id),
  cwi_visual_result      pass_fail,             -- null = not yet inspected
  visual_inspection_date date,
  ndt_company            text,
  xray_number            text,
  ndt_ticket_number      text,
  ndt_method             ndt_method,
  ndt_result             pass_fail,
  ndt_report_id          uuid,
  status                 weld_status not null default 'planned',
  comments               text,                  -- internal only
  -- Optimistic concurrency for the shared grid.
  row_version            integer not null default 1,
  updated_at             timestamptz not null default now(),
  deleted_at             timestamptz,
  unique (weld_line_id, weld_number)
);
create index weld_book_idx  on weld(job_book_id) where deleted_at is null;
create index weld_line_idx  on weld(weld_line_id) where deleted_at is null;
create index weld_date_idx  on weld(job_book_id, weld_date);
create index weld_heat_idx  on weld using gin (heat_numbers);

-- ---------------------------------------------------------------------
-- Torque records
-- ---------------------------------------------------------------------
create table torque_connection (
  id                   uuid primary key default gen_random_uuid(),
  job_book_id          uuid not null references job_book(id) on delete cascade,
  iso_flange_number    text not null,
  iso_number           text,
  flange_pipe_size     text,
  bolt_diameter        text,
  bolt_count           integer,
  required_torque_ft_lb numeric(10,2),
  actual_torque_ft_lb   numeric(10,2),
  wrench_id            uuid references torque_wrench(id),
  wrench_id_raw        text,                    -- as recorded, before resolution
  cp_test_on_flange    boolean not null default false,
  torque_date          date,
  employee_initials    text,
  inspection_date      date,
  inspector_initials   text,
  status               text not null default 'recorded',
  row_version          integer not null default 1,
  updated_at           timestamptz not null default now(),
  deleted_at           timestamptz
);
create index torque_book_idx on torque_connection(job_book_id) where deleted_at is null;

-- ---------------------------------------------------------------------
-- NDE reports
-- ---------------------------------------------------------------------
create table nde_report (
  id                    uuid primary key default gen_random_uuid(),
  job_book_id           uuid not null references job_book(id) on delete cascade,
  report_number         text,
  report_date           date not null,
  ndt_company           text,
  method                ndt_method not null,
  procedure_reference   text,
  revision              text,
  acceptance_criteria   text,
  technician_id         uuid references ndt_technician(id),
  work_order_number     text,
  client_po_afe         text,
  equipment_model       text,
  equipment_serial      text,
  equipment_cal_due_date date,
  -- Free text as printed on the report. Compared against the job book's own
  -- facility/pad to catch a document filed into the wrong book.
  referenced_facility   text,
  referenced_pad        text,
  document_id           uuid references document(id),
  supersedes_report_id  uuid references nde_report(id),
  is_superseded         boolean not null default false,
  created_at            timestamptz not null default now(),
  deleted_at            timestamptz
);

create table nde_report_line (
  id            uuid primary key default gen_random_uuid(),
  nde_report_id uuid not null references nde_report(id) on delete cascade,
  weld_id       uuid references weld(id),
  part_number   text,
  weld_number   text,                            -- as printed, may not resolve
  result        pass_fail,
  location      text,
  welder_code   text,
  weld_joint    text,
  weld_size     text,
  weld_schedule text,
  indications   text
);
create index nde_line_weld_idx on nde_report_line(weld_id);

alter table weld add constraint weld_ndt_report_fk
  foreign key (ndt_report_id) references nde_report(id);

-- ---------------------------------------------------------------------
-- Materials
-- ---------------------------------------------------------------------
create table material_heat (
  id                uuid primary key default gen_random_uuid(),
  job_book_id       uuid not null references job_book(id) on delete cascade,
  heat_number       text not null,
  component_type    text,
  nominal_size      text,
  schedule_or_class text,
  grade             text,
  description       text,
  mtr_document_id   uuid references document(id),
  mtr_status        mtr_status not null default 'missing',
  created_at        timestamptz not null default now(),
  deleted_at        timestamptz,
  unique (job_book_id, heat_number)
);

-- ---------------------------------------------------------------------
-- Pressure testing, cathodic protection, ultrasonic baselines
-- ---------------------------------------------------------------------
create table pressure_test (
  id                     uuid primary key default gen_random_uuid(),
  job_book_id            uuid not null references job_book(id) on delete cascade,
  test_identifier        text not null,
  line_codes             text[] not null default '{}',
  test_date              date,
  test_medium            text,
  test_pressure_psi      numeric(10,2),
  duration_minutes       integer,
  result                 pass_fail,
  recorder_serial        text,
  recorder_cert_id       uuid references certificate(id),
  chart_document_id      uuid references document(id),
  witnessed_by           text,
  created_at             timestamptz not null default now(),
  deleted_at             timestamptz
);

create table cp_test_point (
  id                  uuid primary key default gen_random_uuid(),
  job_book_id         uuid not null references job_book(id) on delete cascade,
  test_point_id       text not null,
  location            text,
  torque_connection_id uuid references torque_connection(id),
  baseline_potential_v numeric(8,3),
  reading_date        date,
  technician          text,
  created_at          timestamptz not null default now(),
  deleted_at          timestamptz
);

create table ut_reading (
  id             uuid primary key default gen_random_uuid(),
  job_book_id    uuid not null references job_book(id) on delete cascade,
  location_id    text not null,
  description    text,
  nominal_wall   numeric(8,4),
  measured_wall  numeric(8,4),
  reading_date   date,
  technician_id  uuid references ndt_technician(id),
  created_at     timestamptz not null default now(),
  deleted_at     timestamptz
);

-- ---------------------------------------------------------------------
-- Compliance flags
-- ---------------------------------------------------------------------
create table compliance_flag (
  id              uuid primary key default gen_random_uuid(),
  job_book_id     uuid not null references job_book(id) on delete cascade,
  rule_id         text not null,
  severity        flag_severity not null,
  title           text not null,
  detail          text not null,
  entity_type     text,
  entity_id       uuid,
  section_number  text,
  fingerprint     text not null,                -- stable id for dedupe across runs
  state           flag_state not null default 'open',
  assigned_to     uuid references app_user(id),
  resolution_note text,
  resolved_by     uuid references app_user(id),
  resolved_at     timestamptz,
  first_seen_at   timestamptz not null default now(),
  last_seen_at    timestamptz not null default now(),
  unique (job_book_id, fingerprint),
  -- Resolution always carries a reason. Auditors ask.
  constraint resolution_has_note check (
    state not in ('resolved','dismissed') or (resolution_note is not null and resolved_by is not null)
  )
);
create index flag_open_idx on compliance_flag(job_book_id, severity) where state = 'open';

-- Inspector comments, when the grant enables them.
create table inspector_comment (
  id          uuid primary key default gen_random_uuid(),
  job_book_id uuid not null references job_book(id) on delete cascade,
  section_id  uuid references job_book_section(id),
  document_id uuid references document(id),
  author_id   uuid not null references app_user(id),
  body        text not null,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------
-- Score snapshots. The weights are versioned, so a score computed last
-- quarter can be reproduced exactly.
-- ---------------------------------------------------------------------
create table score_snapshot (
  id               uuid primary key default gen_random_uuid(),
  job_book_id      uuid not null references job_book(id) on delete cascade,
  book_template_id uuid not null references book_template(id),
  overall_pct      numeric(5,2) not null,
  breakdown_json   jsonb not null,
  computed_at      timestamptz not null default now()
);


-- ═══════════════════════════════════════════════════════════════════
-- 0002_audit.sql
-- ═══════════════════════════════════════════════════════════════════

-- =====================================================================
-- Append-only audit log.
-- The append-only property is enforced by the database, not by convention:
-- rules rewrite UPDATE and DELETE to no-ops, and the privilege grants
-- withhold them regardless. A compromised application role cannot rewrite
-- history.
-- =====================================================================

create table audit_event (
  id           bigserial primary key,
  actor_id     uuid,
  actor_email  text,
  actor_role   user_role,
  job_book_id  uuid,
  entity_type  text not null,
  entity_id    uuid,
  action       text not null,
  before_json  jsonb,
  after_json   jsonb,
  ip_address   inet,
  user_agent   text,
  created_at   timestamptz not null default now()
);
create index audit_book_idx   on audit_event(job_book_id, created_at desc);
create index audit_entity_idx on audit_event(entity_type, entity_id);
create index audit_actor_idx  on audit_event(actor_id, created_at desc);

-- Belt: no role may update or delete, ever.
revoke update, delete, truncate on audit_event from public;
revoke update, delete, truncate on audit_event from anon, authenticated;

-- Braces: even a role that somehow held the privilege gets its statement
-- turned into nothing. DO INSTEAD NOTHING silently discards the write
-- rather than erroring, which is deliberate — a rogue DELETE must not be
-- able to distinguish a protected table from an empty one.
create rule audit_event_no_update as on update to audit_event do instead nothing;
create rule audit_event_no_delete as on delete to audit_event do instead nothing;

-- ---------------------------------------------------------------------
-- Actor resolution. Every audited write is attributed to the calling
-- Supabase auth identity; there is no anonymous path to a write.
-- ---------------------------------------------------------------------
create or replace function current_app_user()
returns app_user
language sql stable security definer set search_path = public
as $$
  select * from app_user
   where auth_user_id = auth.uid()
     and is_active
     and deleted_at is null
   limit 1
$$;

create or replace function current_app_user_id() returns uuid
language sql stable security definer set search_path = public
as $$ select id from app_user where auth_user_id = auth.uid() and is_active and deleted_at is null limit 1 $$;

create or replace function current_app_role() returns user_role
language sql stable security definer set search_path = public
as $$ select role from app_user where auth_user_id = auth.uid() and is_active and deleted_at is null limit 1 $$;

create or replace function current_client_org_id() returns uuid
language sql stable security definer set search_path = public
as $$ select client_org_id from app_user where auth_user_id = auth.uid() and is_active and deleted_at is null limit 1 $$;

-- ---------------------------------------------------------------------
-- Generic audit trigger. Attach to every table carrying compliance data.
-- ---------------------------------------------------------------------
create or replace function audit_trigger()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_actor   app_user;
  v_book_id uuid;
  v_before  jsonb;
  v_after   jsonb;
  v_action  text;
begin
  select * into v_actor from current_app_user();

  if tg_op = 'INSERT' then
    v_before := null; v_after := to_jsonb(new); v_action := 'create';
  elsif tg_op = 'UPDATE' then
    v_before := to_jsonb(old); v_after := to_jsonb(new);
    -- A soft delete is a distinct, separately-queryable action.
    v_action := case
      when to_jsonb(old) ? 'deleted_at'
       and old.deleted_at is null and new.deleted_at is not null then 'soft_delete'
      else 'update' end;
  else
    v_before := to_jsonb(old); v_after := null; v_action := 'hard_delete';
  end if;

  -- Pull the owning book id from whichever column carries it.
  v_book_id := coalesce(
    (v_after ->> 'job_book_id')::uuid,
    (v_before ->> 'job_book_id')::uuid,
    case when tg_table_name = 'job_book'
         then coalesce((v_after ->> 'id')::uuid, (v_before ->> 'id')::uuid) end
  );

  insert into audit_event (
    actor_id, actor_email, actor_role, job_book_id,
    entity_type, entity_id, action, before_json, after_json,
    ip_address, user_agent
  ) values (
    v_actor.id, v_actor.email, v_actor.role, v_book_id,
    tg_table_name,
    coalesce((v_after ->> 'id')::uuid, (v_before ->> 'id')::uuid),
    v_action, v_before, v_after,
    nullif(current_setting('request.headers', true)::jsonb ->> 'x-forwarded-for','')::inet,
    current_setting('request.headers', true)::jsonb ->> 'user-agent'
  );

  return coalesce(new, old);
exception when others then
  -- Never let audit-context extraction (e.g. a malformed header) block the
  -- write path, but never silently drop the event either.
  insert into audit_event (entity_type, entity_id, action, before_json, after_json)
  values (tg_table_name, coalesce((v_after->>'id')::uuid,(v_before->>'id')::uuid),
          v_action || '_degraded', v_before, v_after);
  return coalesce(new, old);
end;
$$;

do $$
declare t text;
begin
  foreach t in array array[
    'client_org','app_user','project','job_book','job_assignment','inspector_grant',
    'book_template','section_definition','job_book_section','document',
    'welder','welder_qualification','cwi','ndt_technician','torque_wrench','certificate',
    'weld_line','weld','torque_connection','nde_report','nde_report_line',
    'material_heat','pressure_test','cp_test_point','ut_reading',
    'compliance_flag','inspector_comment'
  ] loop
    execute format(
      'create trigger %I_audit after insert or update or delete on %I
         for each row execute function audit_trigger()', t, t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Document access is itself an audited event — inspectors will ask who
-- read what, and a read leaves no row behind otherwise.
-- ---------------------------------------------------------------------
create or replace function log_document_access(
  p_document_id uuid, p_action text default 'download'
) returns void
language plpgsql security definer set search_path = public
as $$
declare v_actor app_user; v_doc document;
begin
  select * into v_actor from current_app_user();
  select * into v_doc from document where id = p_document_id;
  insert into audit_event (actor_id, actor_email, actor_role, job_book_id,
                           entity_type, entity_id, action, after_json)
  values (v_actor.id, v_actor.email, v_actor.role, v_doc.job_book_id,
          'document', p_document_id, p_action,
          jsonb_build_object('filename', v_doc.normalized_filename,
                             'sha256', v_doc.sha256));
end;
$$;

-- ---------------------------------------------------------------------
-- Section approval as a two-person control. Approval cannot be performed
-- by the user who marked the section ready, and cannot be performed by a
-- tech at all — checked here so it holds for any caller, not just the UI.
-- ---------------------------------------------------------------------
create or replace function approve_section(p_section_id uuid)
returns job_book_section
language plpgsql security definer set search_path = public
as $$
declare v_actor app_user; v_section job_book_section;
begin
  select * into v_actor from current_app_user();
  if v_actor.id is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if v_actor.role not in ('fortress_admin','qaqc_manager') then
    raise exception 'section approval requires QA/QC Manager or Admin' using errcode = '42501';
  end if;

  select * into v_section from job_book_section where id = p_section_id for update;
  if v_section.id is null then
    raise exception 'section not found' using errcode = 'P0002';
  end if;
  if v_section.ready_for_review_by = v_actor.id then
    raise exception 'a section may not be approved by the user who submitted it'
      using errcode = '42501';
  end if;

  update job_book_section
     set status = 'approved', approved_by = v_actor.id, approved_at = now()
   where id = p_section_id
  returning * into v_section;

  return v_section;
end;
$$;


-- ═══════════════════════════════════════════════════════════════════
-- 0003_rls.sql
-- ═══════════════════════════════════════════════════════════════════

-- =====================================================================
-- Row Level Security.
-- Client isolation and inspector scoping are enforced here, in the
-- database, on the assumption that the API will be probed directly. The
-- application layer's checks are a convenience, never the control.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Visibility predicates. Each returns the set of job books a caller may
-- see, by role. Written as SQL functions so every policy shares one
-- definition and a fix lands everywhere at once.
-- ---------------------------------------------------------------------

-- Fortress staff: any non-client, non-inspector role.
create or replace function is_fortress_staff() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(current_app_role() in
    ('fortress_admin','qaqc_manager','qaqc_tech','fortress_read_only'), false)
$$;

create or replace function is_fortress_writer() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(current_app_role() in
    ('fortress_admin','qaqc_manager','qaqc_tech'), false)
$$;

create or replace function is_manager_or_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(current_app_role() in ('fortress_admin','qaqc_manager'), false)
$$;

-- A live, unrevoked, unexpired grant on this specific book.
create or replace function has_live_inspector_grant(p_book uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from inspector_grant g
     where g.job_book_id = p_book
       and g.user_id = current_app_user_id()
       and g.revoked_at is null
       and (g.expires_at is null or g.expires_at > now())
  )
$$;

-- Readable book set, by role:
--   admin / manager / read-only  -> every Fortress book
--   tech                         -> only books they are assigned to
--   client user                  -> only books under their own org
--   inspector                    -> only books with a live grant
create or replace function can_read_job_book(p_book uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case current_app_role()
    when 'fortress_admin'      then true
    when 'qaqc_manager'        then true
    when 'fortress_read_only'  then true
    when 'qaqc_tech' then exists (
      select 1 from job_assignment a
       where a.job_book_id = p_book and a.user_id = current_app_user_id())
    when 'client_user' then exists (
      select 1 from job_book b
        join project p on p.id = b.project_id
       where b.id = p_book
         and p.client_org_id = current_client_org_id()
         and b.deleted_at is null)
    when 'third_party_inspector' then has_live_inspector_grant(p_book)
    else false
  end
$$;

create or replace function can_write_job_book(p_book uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case current_app_role()
    when 'fortress_admin' then true
    when 'qaqc_manager'   then true
    when 'qaqc_tech' then exists (
      select 1 from job_assignment a
       where a.job_book_id = p_book and a.user_id = current_app_user_id())
    else false     -- read-only staff, clients and inspectors never write
  end
$$;

-- External readers (clients, inspectors) see only what has been approved.
-- Draft and unapproved records are internal until a manager says otherwise.
create or replace function is_external_reader() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(current_app_role() in ('client_user','third_party_inspector'), false)
$$;

-- ---------------------------------------------------------------------
-- Enable RLS everywhere. No table carrying job data is left open.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'client_org','app_user','project','job_book','job_assignment','inspector_grant',
    'book_template','section_definition','job_book_section','document',
    'welder','welder_qualification','cwi','ndt_technician','torque_wrench','certificate',
    'weld_line','weld','torque_connection','nde_report','nde_report_line',
    'material_heat','pressure_test','cp_test_point','ut_reading',
    'compliance_flag','inspector_comment','score_snapshot','audit_event'
  ] loop
    execute format('alter table %I enable row level security', t);
    -- FORCE so that even the table owner is subject to policy; without it a
    -- migration or a definer function running as owner would bypass RLS.
    execute format('alter table %I force row level security', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Org / project / book
-- ---------------------------------------------------------------------
create policy client_org_read on client_org for select using (
  is_fortress_staff() or id = current_client_org_id()
);
create policy client_org_write on client_org for all using (
  current_app_role() = 'fortress_admin'
) with check (current_app_role() = 'fortress_admin');

-- A user may always read themselves. Fortress staff read all users. A
-- client user may read only users inside their own org, so that the user
-- table cannot be used to enumerate other operators.
create policy app_user_read on app_user for select using (
  auth_user_id = auth.uid()
  or is_fortress_staff()
  or (current_app_role() = 'client_user' and client_org_id = current_client_org_id())
);
create policy app_user_write on app_user for all using (
  current_app_role() = 'fortress_admin'
) with check (current_app_role() = 'fortress_admin');

create policy project_read on project for select using (
  is_fortress_staff()
  or client_org_id = current_client_org_id()
  or exists (select 1 from job_book b
              where b.project_id = project.id and has_live_inspector_grant(b.id))
);
create policy project_write on project for all using (is_manager_or_admin())
  with check (is_manager_or_admin());

create policy job_book_read on job_book for select using (
  deleted_at is null and can_read_job_book(id)
);
create policy job_book_insert on job_book for insert with check (is_manager_or_admin());
create policy job_book_update on job_book for update using (can_write_job_book(id))
  with check (can_write_job_book(id));

create policy job_assignment_read on job_assignment for select using (
  is_fortress_staff() or user_id = current_app_user_id()
);
create policy job_assignment_write on job_assignment for all using (is_manager_or_admin())
  with check (is_manager_or_admin());

-- An inspector may see their own grant, and nothing about anyone else's.
create policy inspector_grant_read on inspector_grant for select using (
  is_fortress_staff() or user_id = current_app_user_id()
);
create policy inspector_grant_write on inspector_grant for all using (is_manager_or_admin())
  with check (is_manager_or_admin());

-- ---------------------------------------------------------------------
-- Templates are reference data: readable by any authenticated caller,
-- writable only by an admin.
-- ---------------------------------------------------------------------
create policy book_template_read on book_template for select
  using (current_app_user_id() is not null);
create policy book_template_write on book_template for all
  using (current_app_role() = 'fortress_admin')
  with check (current_app_role() = 'fortress_admin');

create policy section_definition_read on section_definition for select
  using (current_app_user_id() is not null);
create policy section_definition_write on section_definition for all
  using (current_app_role() = 'fortress_admin')
  with check (current_app_role() = 'fortress_admin');

-- ---------------------------------------------------------------------
-- Sections. External readers never see internal notes; the column is
-- stripped by the client-facing view below rather than by the browser.
-- ---------------------------------------------------------------------
create policy job_book_section_read on job_book_section for select using (
  can_read_job_book(job_book_id)
);
create policy job_book_section_write on job_book_section for all
  using (can_write_job_book(job_book_id))
  with check (can_write_job_book(job_book_id));

-- ---------------------------------------------------------------------
-- Documents. Fortress sees everything not soft-deleted. Clients and
-- inspectors see only approved documents carrying a visibility that
-- includes them — an unapproved upload is invisible outside Fortress.
-- ---------------------------------------------------------------------
create policy document_read on document for select using (
  deleted_at is null
  and can_read_job_book(job_book_id)
  and (
    is_fortress_staff()
    or (current_app_role() = 'client_user'
        and approved_at is not null and visibility in ('client'))
    or (current_app_role() = 'third_party_inspector'
        and approved_at is not null and visibility in ('client','inspector'))
  )
);
create policy document_write on document for all
  using (can_write_job_book(job_book_id))
  with check (can_write_job_book(job_book_id));

-- ---------------------------------------------------------------------
-- Personnel and equipment are Fortress-wide reference entities. Clients
-- and inspectors reach them only through the records of a book they can
-- already see, so reads are gated on holding any readable book at all.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['welder','cwi','ndt_technician','torque_wrench'] loop
    execute format($p$
      create policy %1$s_read on %1$s for select using (
        deleted_at is null and current_app_user_id() is not null
      );
      create policy %1$s_write on %1$s for all
        using (is_fortress_writer()) with check (is_fortress_writer());
    $p$, t);
  end loop;
end $$;

create policy welder_qual_read on welder_qualification for select
  using (current_app_user_id() is not null);
create policy welder_qual_write on welder_qualification for all
  using (is_fortress_writer()) with check (is_fortress_writer());

create policy certificate_read on certificate for select using (
  deleted_at is null
  and (job_book_id is null or can_read_job_book(job_book_id))
);
create policy certificate_write on certificate for all
  using (is_fortress_writer()) with check (is_fortress_writer());

-- ---------------------------------------------------------------------
-- Record tables. One policy shape, applied to every table that carries a
-- job_book_id, so a new record type cannot be added without inheriting
-- isolation.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'weld_line','weld','torque_connection','nde_report',
    'material_heat','pressure_test','cp_test_point','ut_reading','score_snapshot'
  ] loop
    execute format($p$
      create policy %1$s_read on %1$s for select
        using (can_read_job_book(job_book_id));
      create policy %1$s_write on %1$s for all
        using (can_write_job_book(job_book_id))
        with check (can_write_job_book(job_book_id));
    $p$, t);
  end loop;
end $$;

-- Report lines inherit their parent report's book.
create policy nde_line_read on nde_report_line for select using (
  exists (select 1 from nde_report r
           where r.id = nde_report_id and can_read_job_book(r.job_book_id))
);
create policy nde_line_write on nde_report_line for all using (
  exists (select 1 from nde_report r
           where r.id = nde_report_id and can_write_job_book(r.job_book_id))
) with check (
  exists (select 1 from nde_report r
           where r.id = nde_report_id and can_write_job_book(r.job_book_id))
);

-- ---------------------------------------------------------------------
-- The flag queue is internal. Clients and inspectors never see the raw
-- deficiency list for a book, only its completion story.
-- ---------------------------------------------------------------------
create policy compliance_flag_read on compliance_flag for select using (
  is_fortress_staff() and can_read_job_book(job_book_id)
);
create policy compliance_flag_write on compliance_flag for all
  using (is_fortress_writer() and can_write_job_book(job_book_id))
  with check (is_fortress_writer() and can_write_job_book(job_book_id));

-- An inspector may write a comment only where the grant enables it, and
-- only as themselves.
create policy inspector_comment_read on inspector_comment for select using (
  can_read_job_book(job_book_id)
);
create policy inspector_comment_insert on inspector_comment for insert with check (
  author_id = current_app_user_id()
  and (
    is_fortress_writer()
    or exists (select 1 from inspector_grant g
                where g.job_book_id = inspector_comment.job_book_id
                  and g.user_id = current_app_user_id()
                  and g.can_comment
                  and g.revoked_at is null
                  and (g.expires_at is null or g.expires_at > now()))
  )
);

-- ---------------------------------------------------------------------
-- Audit log: readable by admins outright and by managers for books they
-- can reach; writable by no one through the API. INSERT happens only
-- inside SECURITY DEFINER triggers, which is why no insert policy exists.
-- ---------------------------------------------------------------------
create policy audit_read on audit_event for select using (
  current_app_role() = 'fortress_admin'
  or (current_app_role() = 'qaqc_manager'
      and job_book_id is not null and can_read_job_book(job_book_id))
);

-- ---------------------------------------------------------------------
-- Client-facing views. Internal-only columns are dropped server-side, so
-- they never enter a response payload that a client could inspect.
-- security_invoker keeps the caller's RLS in force through the view.
-- ---------------------------------------------------------------------
create view client_section_v with (security_invoker = true) as
  select id, job_book_id, section_definition_id, status, na_reason,
         approved_at, computed_pct
    from job_book_section;

create view client_weld_v with (security_invoker = true) as
  select id, weld_line_id, job_book_id, weld_number, weld_date, joint_type,
         component_description, heat_numbers, cwi_visual_result,
         visual_inspection_date, ndt_method, ndt_result, status
    from weld
   where deleted_at is null;

comment on view client_weld_v is
  'Client/inspector projection of weld: the internal comments column and the
   per-pass welder identities are absent by construction.';

grant select on client_section_v, client_weld_v to authenticated;


