do $$
declare v_facility_tpl uuid;
begin
  insert into book_template (book_type, version, effective_date, is_active)
  values ('facility', 1, date '2026-01-01', true)
  returning id into v_facility_tpl;

  -- Weights sum to 100 across scoring sections.
  insert into section_definition
    (book_template_id, section_number, sort_order, title, applies_to, weight,
     requirement_type, min_documents, linked_record_type, is_required,
     is_supplemental, notes)
  values
    (v_facility_tpl, '1', 1, 'Job Book Checklist', 'both', 0, 'document', 1, null, true, false, 'Generated by the application from live status; carries no weight.'),
    (v_facility_tpl, '2', 2, 'Facility / Flow Line Overview', 'both', 2, 'document', 2, null, true, false, 'Drawing set — original plus redline.'),
    (v_facility_tpl, '3', 3, 'Operator Piping Specification', 'both', 0.5, 'document', 1, null, true, false, 'Current revision.'),
    (v_facility_tpl, '4', 4, 'Welding Procedure Specification (WPS)', 'both', 0.25, 'document', 1, null, true, false, null),
    (v_facility_tpl, '5', 5, 'Welding Procedure Qualification Record (PQR)', 'both', 0.25, 'document', 1, null, true, false, null),
    (v_facility_tpl, '6', 6, 'Welder Performance Qualifications (WPQ)', 'both', 3, 'personnel_certs', 1, 'welder', true, false, null),
    (v_facility_tpl, '7', 7, 'Certified Welding Inspector Credentials', 'both', 0.5, 'personnel_certs', 1, 'cwi', true, false, null),
    (v_facility_tpl, '8', 8, 'Non-Destructive Testing Technician Credentials', 'both', 1, 'personnel_certs', 1, 'ndt_technician', true, false, null),
    (v_facility_tpl, '9', 9, 'Non-Destructive Testing Procedures', 'both', 0.5, 'document', 4, null, true, false, 'One procedure per method in use: MT, PT, RT, UT.'),
    (v_facility_tpl, '10', 10, 'NDT Job Logs and Films', 'both', 7, 'records', 1, 'nde_report', true, false, 'Films provided separately.'),
    (v_facility_tpl, '11', 11, 'Weld Log Overview Sheet with Inspection Percentages', 'both', 0, 'derived', 1, 'weld', true, false, 'Rolls up section 12; never scored independently.'),
    (v_facility_tpl, '12', 12, 'Detailed Weld Log', 'both', 14, 'records', 1, 'weld', true, false, null),
    (v_facility_tpl, '13', 13, 'Torque Wrench Calibration Certificates', 'both', 3, 'equipment_certs', 1, 'torque_wrench', true, false, null),
    (v_facility_tpl, '14', 14, 'Detailed Torque Log', 'both', 8, 'records', 1, 'torque_connection', true, false, null),
    (v_facility_tpl, '15', 15, 'Material Test Reports', 'both', 12, 'records', 1, 'material_heat', true, false, 'One MTR per heat number referenced by any weld.'),
    (v_facility_tpl, '16', 16, 'Pressure Testing Procedure with P&ID Valve Orientation', 'both', 1, 'document', 1, null, true, false, null),
    (v_facility_tpl, '17', 17, 'Pressure Testing Results with Recorder Calibration Certificates', 'both', 10, 'records', 1, 'pressure_test', true, false, null),
    (v_facility_tpl, '18', 18, 'Cathodic Protection Testing Locations and Baseline Results', 'both', 4, 'records', 1, 'cp_test_point', true, false, null),
    (v_facility_tpl, '19', 19, 'Ultrasonic Testing Locations and Baseline Results', 'facility', 4, 'records', 1, 'ut_reading', true, false, null),
    (v_facility_tpl, '20', 20, 'As-Built P&IDs', 'facility', 5, 'document', 1, null, true, false, null),
    (v_facility_tpl, '21', 21, 'Isometric Weld and X-Ray Map', 'facility', 10, 'records', 1, 'isometric', true, false, 'One drawing per isometric referenced by either log.'),
    (v_facility_tpl, '22', 22, 'Isometric Heat Number and Torque Map', 'facility', 10, 'records', 1, 'isometric', true, false, 'One drawing per isometric referenced by either log.'),
    (v_facility_tpl, '23', 23, 'Coating Inspection', 'both', 4, 'records', 1, 'coating_inspection', false, false, 'Off-checklist. Scored per construction area when enabled for a job.'),
    (v_facility_tpl, 'S1', 24, 'Flexpipe Daily Field Reports', 'both', 0, 'supplemental', 1, null, false, true, 'Delivered in DP452; appears on no checklist revision.');
end $$;


-- ═══════════════════════════════════════════════════════════════════
-- 0005_expected_scope.sql
-- ═══════════════════════════════════════════════════════════════════

-- =====================================================================
-- Declared scope.
--
-- Every percentage in this application is a fraction, and before this
-- migration the denominator was "records entered so far". That makes a
-- partly-entered section read as complete: 100 joints typed out of 2,342,
-- all of them filled in correctly, scored 100%.
--
-- expected_count is the denominator declared at job setup from the drawing
-- set. It is a floor, not a cap — the scoring engine takes
-- max(expected, actual), so a job that runs bigger than scoped cannot push
-- a section past 100%, and a scope guessed low cannot make a half-finished
-- section look finished.
-- =====================================================================

alter table job_book_section
  add column expected_count integer
    check (expected_count is null or expected_count >= 0);

comment on column job_book_section.expected_count is
  'Records or documents this section is expected to hold when complete,
   declared at job setup. The scoring denominator. Null means undeclared,
   in which case the section scores against what exists.';

-- Joints per line, off the isometrics. Summed across lines, this scopes
-- section 12 more accurately than a single book-wide figure.
alter table weld_line
  add column expected_weld_count integer
    check (expected_weld_count is null or expected_weld_count >= 0);

comment on column weld_line.expected_weld_count is
  'Joints this line is expected to carry, from the isometric.';

-- ---------------------------------------------------------------------
-- Scaffold a new book with all checklist sections in one transaction.
--
-- A book that exists with only some of its sections is worse than no book:
-- its percentage is computed over a partial denominator and reads high.
-- Creating the sections here, rather than in application code, means a
-- book cannot come into existence half-scaffolded.
-- ---------------------------------------------------------------------
create or replace function create_job_book(
  p_project_id       uuid,
  p_book_type        book_type,
  p_job_number       text,
  p_header           jsonb default '{}'::jsonb,
  p_thresholds       jsonb default '{}'::jsonb,
  -- [{"section_number": "12", "expected_count": 2342}, ...]
  p_scope            jsonb default '[]'::jsonb
) returns job_book
language plpgsql security definer set search_path = public
as $$
declare
  v_actor    app_user;
  v_template book_template;
  v_book     job_book;
  v_def      section_definition;
  v_expected integer;
  v_applies  boolean;
begin
  select * into v_actor from current_app_user();
  if v_actor.id is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if v_actor.role not in ('fortress_admin','qaqc_manager') then
    raise exception 'creating a job book requires QA/QC Manager or Admin'
      using errcode = '42501';
  end if;

  select * into v_template
    from book_template
   where book_type = p_book_type and is_active
   order by version desc
   limit 1;
  if v_template.id is null then
    raise exception 'no active template for book type %', p_book_type using errcode = 'P0002';
  end if;

  insert into job_book (
    project_id, book_template_id, book_type, job_number,
    facility_name, drill_pad_name, well_names, construction_company,
    welding_company, cwi_names, pipe_size_in, pipe_schedule, pipe_grade,
    status, target_turnover_date, construction_start, construction_end,
    required_xray_pct, required_torque_inspect_pct, torque_tolerance_pct,
    cert_expiry_warning_days, created_by
  ) values (
    p_project_id, v_template.id, p_book_type, p_job_number,
    p_header ->> 'facility_name',
    p_header ->> 'drill_pad_name',
    coalesce((select array_agg(value) from jsonb_array_elements_text(
      coalesce(p_header -> 'well_names', '[]'::jsonb))), '{}'),
    p_header ->> 'construction_company',
    p_header ->> 'welding_company',
    coalesce((select array_agg(value) from jsonb_array_elements_text(
      coalesce(p_header -> 'cwi_names', '[]'::jsonb))), '{}'),
    p_header ->> 'pipe_size_in',
    p_header ->> 'pipe_schedule',
    p_header ->> 'pipe_grade',
    'setup',
    (p_header ->> 'target_turnover_date')::date,
    (p_header ->> 'construction_start')::date,
    (p_header ->> 'construction_end')::date,
    coalesce((p_thresholds ->> 'required_xray_pct')::numeric, 10),
    coalesce((p_thresholds ->> 'required_torque_inspect_pct')::numeric, 10),
    coalesce((p_thresholds ->> 'torque_tolerance_pct')::numeric, 5),
    coalesce((p_thresholds ->> 'cert_expiry_warning_days')::integer, 60),
    v_actor.id
  ) returning * into v_book;

  for v_def in
    select * from section_definition
     where book_template_id = v_template.id
     order by sort_order
  loop
    v_applies := v_def.applies_to = 'both' or v_def.applies_to::text = p_book_type::text;
    select (elem ->> 'expected_count')::integer into v_expected
      from jsonb_array_elements(p_scope) elem
     where elem ->> 'section_number' = v_def.section_number
     limit 1;

    insert into job_book_section (
      job_book_id, section_definition_id, status, na_reason, expected_count
    ) values (
      v_book.id, v_def.id,
      case
        when not v_applies then 'na'
        -- Scoping a section to zero is a statement that it has no work in
        -- it, which is what N/A means. A zero denominator would instead
        -- park it at 0% forever.
        when v_expected = 0 then 'na'
        else 'not_started'
      end,
      case
        when not v_applies then v_def.applies_to || '-only section; not applicable to a '
                               || p_book_type || ' book.'
        when v_expected = 0 then 'Scoped to zero at job setup — this job has no work of this kind.'
      end,
      case when v_expected > 0 then v_expected end
    );
  end loop;

  return v_book;
end;
$$;


-- ═══════════════════════════════════════════════════════════════════
-- 0006_facility_books.sql
-- ═══════════════════════════════════════════════════════════════════

-- =====================================================================
-- Facility job book support.
--
-- Greeley Crescent DP-318 is the first facility book in the system. It
-- differs from a flowline book in five ways, and each one is a schema
-- change rather than a branch in application code, so that a third book
-- type later is configuration again.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Optional, off-checklist sections.
--
-- Distinct from supplemental. A supplemental section is never scored — it
-- is a home for documents that arrived without a category. An optional
-- section carries real weight when a job enables it and leaves the
-- denominator entirely when it does not, so enabling coating inspection
-- can lower a book's percentage and disabling it can never raise one.
-- ---------------------------------------------------------------------
alter table section_definition
  add column is_optional boolean not null default false;

comment on column section_definition.is_optional is
  'Off the governing checklist but scored when a job enables it, e.g.
   section 23 Coating Inspection. Enabled per job via
   job_book.enabled_optional_sections.';

alter table job_book
  add column enabled_optional_sections text[] not null default '{}',
  add column business_unit             text,
  add column qaqc_representative       text,
  -- Facility work is divided into construction areas; the denominator for
  -- per-area sections such as coating inspection.
  add column construction_areas        text[] not null default '{}',
  -- Used for the inspection-tier calculation where a weld row carries no
  -- design pressure of its own.
  add column default_design_pressure_psi numeric(10,2);

-- ---------------------------------------------------------------------
-- 2. Work organised by construction area, not by line.
--
-- weld_line remains the grouping entity for both book types, because
-- everything consuming it asks the same question either way — which group
-- is this weld in. Only the label changes.
-- ---------------------------------------------------------------------
create type weld_grouping_kind as enum ('line', 'construction_area');

alter table weld_line
  add column grouping_kind weld_grouping_kind not null default 'line';

alter table weld
  add column construction_area text,
  add column equipment_tag     text,
  add column isometric_number  text,
  add column pressure_test_ref text;

create index weld_area_idx on weld(job_book_id, construction_area) where deleted_at is null;
create index weld_iso_idx  on weld(job_book_id, isometric_number)  where deleted_at is null;

-- ---------------------------------------------------------------------
-- 3. One welder stamp per weld, not four pass assignments.
--
-- Both shapes coexist on the same table. A facility weld populates
-- welder_id and leaves the four pass columns null; the rollups read
-- whichever is present, so per-welder percentages, qualification checks
-- and continuity are computed by one code path for both book types.
-- ---------------------------------------------------------------------
alter table weld
  add column welder_stamp text,
  add column welder_id    uuid references welder(id);

alter table weld add constraint weld_has_one_welder_shape check (
  -- Either the four-pass shape or the single-stamp shape, never both.
  welder_id is null
  or (root_welder_id is null and hot_welder_id is null
      and fill_welder_id is null and cap_welder_id is null)
);

-- ---------------------------------------------------------------------
-- 4. Required torque is a range.
--
-- A facility log specifies 130-260 ft-lb rather than a single figure, so
-- "is the actual within spec" is a containment test rather than a
-- tolerance guess. A point value sets both bounds and reads identically.
-- ---------------------------------------------------------------------
alter table torque_connection
  add column required_torque_min_ft_lb numeric(10,2),
  add column required_torque_max_ft_lb numeric(10,2);

alter table torque_connection add constraint torque_range_ordered check (
  required_torque_min_ft_lb is null
  or required_torque_max_ft_lb is null
  or required_torque_min_ft_lb <= required_torque_max_ft_lb
);

-- Backfill the existing flowline books: a point value is a degenerate range.
update torque_connection
   set required_torque_min_ft_lb = required_torque_ft_lb,
       required_torque_max_ft_lb = required_torque_ft_lb
 where required_torque_ft_lb is not null
   and required_torque_min_ft_lb is null;

-- ---------------------------------------------------------------------
-- 5. Pipe engineering inputs, per weld.
--
-- A facility weld log derives each weld's inspection obligation from the
-- pipe rather than from a flat job-wide percentage, so these are per-weld.
-- The derived values (hoop stress, % SMYS, tier) are deliberately NOT
-- stored: they are recomputed from these inputs whenever an input or a
-- tier rule changes, and a stored copy would go stale silently.
-- ---------------------------------------------------------------------
alter table weld
  add column pipe_size_schedule   text,
  add column pipe_grade           text,
  add column design_pressure_psi  numeric(10,2);

-- NPS reference dimensions, imported from the weld log's own
-- 'NPS and Dimensions' sheet so a book's tiers are reproducible against
-- the table that produced them.
create table nps_dimension (
  id             uuid primary key default gen_random_uuid(),
  book_template_id uuid references book_template(id),
  job_book_id    uuid references job_book(id) on delete cascade,
  size_schedule  text not null,
  nps            text not null,
  schedule       text not null,
  od_in          numeric(8,4) not null check (od_in > 0),
  wall_in        numeric(8,4) not null check (wall_in > 0),
  source         text not null default 'ASME B36.10M',
  created_at     timestamptz not null default now(),
  unique (job_book_id, size_schedule)
);

-- ---------------------------------------------------------------------
-- Inspection tier rules.
--
-- In a table rather than in code because the 20% SMYS break point is
-- INFERRED from the Greeley workbook, not quoted from a code clause, and
-- still needs QA/QC confirmation. Confirming it — or moving it to 30% for
-- a different operator's spec — is a row edit and a recomputation, not a
-- deploy. `is_confirmed` lets the UI say which it is next to any number
-- derived from it.
-- ---------------------------------------------------------------------
create table inspection_tier_rule (
  id                    uuid primary key default gen_random_uuid(),
  book_template_id      uuid references book_template(id),
  job_book_id           uuid references job_book(id) on delete cascade,
  rule_key              text not null,
  sort_order            integer not null default 0,
  min_pct_smys          numeric(6,4) not null check (min_pct_smys >= 0),
  max_pct_smys          numeric(6,4) check (max_pct_smys is null or max_pct_smys > min_pct_smys),
  tier                  text not null,
  required_ndt_fraction numeric(5,4) not null default 0
    check (required_ndt_fraction >= 0 and required_ndt_fraction <= 1),
  requires_full_visual  boolean not null default true,
  is_confirmed          boolean not null default false,
  note                  text,
  created_at            timestamptz not null default now()
);

comment on table inspection_tier_rule is
  'Bands of % SMYS and the inspection each requires. The 20% break point is
   inferred from the DP-318 weld log and unconfirmed; is_confirmed marks
   whether QA/QC has signed off on a band.';

-- Coating inspection records, one per construction area (section 23).
create table coating_inspection (
  id                 uuid primary key default gen_random_uuid(),
  job_book_id        uuid not null references job_book(id) on delete cascade,
  construction_area  text not null,
  inspection_date    date,
  inspector          text,
  -- Photographs filed with no readings count as started, not as done.
  has_structured_data boolean not null default false,
  document_count     integer not null default 0,
  notes              text,
  created_at         timestamptz not null default now(),
  deleted_at         timestamptz,
  unique (job_book_id, construction_area)
);

-- ---------------------------------------------------------------------
-- Isolation and audit for the new tables, on the same shared predicates
-- as everything else. A record type added without these would be a hole.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['nps_dimension','inspection_tier_rule','coating_inspection'] loop
    execute format('alter table %I enable row level security', t);
    execute format('alter table %I force row level security', t);
    execute format(
      'create trigger %I_audit after insert or update or delete on %I
         for each row execute function audit_trigger()', t, t);
  end loop;
end $$;

create policy coating_inspection_read on coating_inspection for select
  using (can_read_job_book(job_book_id));
create policy coating_inspection_write on coating_inspection for all
  using (can_write_job_book(job_book_id))
  with check (can_write_job_book(job_book_id));

-- Reference tables: readable where the owning book is, or globally when
-- attached to a template rather than a job.
create policy nps_dimension_read on nps_dimension for select
  using (job_book_id is null or can_read_job_book(job_book_id));
create policy nps_dimension_write on nps_dimension for all
  using (is_fortress_writer()) with check (is_fortress_writer());

create policy tier_rule_read on inspection_tier_rule for select
  using (job_book_id is null or can_read_job_book(job_book_id));
-- Moving a tier threshold changes every derived inspection obligation in
-- the book, so it is an admin action, not a tech's.
create policy tier_rule_write on inspection_tier_rule for all
  using (is_manager_or_admin()) with check (is_manager_or_admin());


-- ═══════════════════════════════════════════════════════════════════
-- 0007_calibration_certificates.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- The certificate is the calibration record.
--
-- This application previously reported a torque wrench as having no
-- calibration on record whenever nobody had typed a date into the torque
-- log's roster block — while the wrench's calibration certificate sat in
-- section 13 of the same book. On the Greeley Crescent DP-318 book that
-- produced eighteen findings against connections torqued with a wrench
-- calibrated four months before the work.
--
-- A filed certificate this application has not managed to read is an
-- ingestion gap on our side. It is not a deficiency in the book, and the
-- schema now says so in three places:
--
--   · `cert_read` separates "we have not read it" from "it is not there".
--   · `roster_claimed_calibration_date` keeps the log's typed summary
--     beside the certificate instead of in place of it, so the two can
--     disagree in public.
--   · `certificate.issue_date` becomes nullable, because a certificate on
--     file whose dates have not been read has no known issue date, and
--     inventing one makes an unread page look verified.
-- ---------------------------------------------------------------------

alter table torque_wrench
  add column cert_read boolean not null default false,
  add column roster_claimed_calibration_date date,
  -- The full serial as printed; the log names wrenches by its last four.
  add column serial_number text,
  add column manufacturer text,
  add column model text,
  add column certificate_number text,
  add column calibration_range_min_ft_lb numeric(10,2),
  add column calibration_range_max_ft_lb numeric(10,2),
  add column calibration_frequency text,
  add column calibration_status text
    check (calibration_status is null or calibration_status in ('pass','fail'));

comment on column torque_wrench.cert_read is
  'Whether the certificate on file has actually been read into this book. '
  'False with cert_on_file true means unread, which is an ingestion gap, '
  'not a missing calibration.';

comment on column torque_wrench.roster_claimed_calibration_date is
  'What the torque log roster block claims. Compared against the '
  'certificate, never substituted for it: on DP-318 one roster line '
  'transcribes the handwritten date the wrench went into service.';

-- A wrench cannot be recorded as read without a certificate to read.
alter table torque_wrench
  add constraint cert_read_requires_cert
  check (not cert_read or cert_on_file);

-- Calibration dates come off the certificate, so they are only meaningful
-- once it has been read.
alter table torque_wrench
  add constraint calibration_dates_require_read_cert
  check (cert_read or (last_calibration_date is null and calibration_due_date is null));

-- A window that closes before it opens is a transcription error.
alter table torque_wrench
  add constraint calibration_window_ordered
  check (
    last_calibration_date is null or calibration_due_date is null
    or calibration_due_date >= last_calibration_date
  );

alter table certificate
  alter column issue_date drop not null;

comment on column certificate.issue_date is
  'Null where the certificate is on file but has not been read. Validity '
  'checks refuse to certify work against an unknown issue date, so an '
  'unread page never passes as a valid one.';

-- An expiry with no issue date is half a window, and half a window reads
-- as an unbounded one to anything comparing dates.
alter table certificate
  add constraint expiry_requires_issue_date
  check (expiry_date is null or issue_date is not null);

alter table certificate
  add constraint certificate_window_ordered
  check (issue_date is null or expiry_date is null or expiry_date >= issue_date);


-- ═══════════════════════════════════════════════════════════════════
-- 0008_computed_score_cache.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- `job_book_section.computed_pct` is a cache, and it was lying.
--
-- The completion percentage is derived: a pure function of the records,
-- the declared scope and the section weights. The Fortress-facing screens
-- run that function on every request, so they were always right. The
-- stored column, however, is what `client_section_v` returns — and nothing
-- ever wrote it. Every row sat at the 0.00 default.
--
-- That is a two-audience divergence: staff opened a book at 90% while the
-- operator's own view of the same data reported 0%. For a turnover tool
-- that is worse than showing no figure at all, because both parties
-- believe they are reading the record.
--
-- The fix is not to compute the score in SQL — the engine is a tested
-- TypeScript module and having a second implementation in plpgsql would
-- guarantee the two drift. It is to make the cache honest: stamp it when
-- it is written, and never serve a number that cannot say how old it is.
-- ---------------------------------------------------------------------

alter table job_book_section
  add column computed_at timestamptz,
  -- Collected evidence, cached beside approved evidence.
  --
  -- A section scores on documents a second person has *approved* — that is
  -- the two-person control, and it does not bend. But a tech who uploads
  -- eleven drawings and watches the section sit at 0% cannot tell a working
  -- upload from a broken one, and will stop trusting the screen. Both
  -- figures are carried so it can say "100% collected, awaiting approval"
  -- instead of an unexplained zero.
  add column collected_pct numeric(5,2) not null default 0;

comment on column job_book_section.collected_pct is
  'Cache of the same score over evidence collected rather than approved. '
  'Never below computed_pct; the gap is work awaiting a signature.';

-- Approved evidence is a subset of collected evidence, always.
alter table job_book_section
  add constraint collected_at_least_approved
  check (collected_pct >= computed_pct);

comment on column job_book_section.computed_pct is
  'Cache of the derived completion score. Authoritative source is the '
  'scoring engine; this column exists for readers that do not run it, '
  'chiefly client_section_v. Always written together with computed_at.';

comment on column job_book_section.computed_at is
  'When computed_pct was last written. Null means never computed, which '
  'readers must render as "not yet scored" rather than as 0%.';

-- A percentage with no timestamp is indistinguishable from a current one,
-- so the two move together or not at all.
alter table job_book_section
  add constraint computed_pct_is_stamped
  check ((computed_pct = 0 and computed_at is null) or computed_at is not null);

-- Writing the score is the only thing that may stamp it. A hand-edited
-- percentage with a fresh timestamp would be indistinguishable from a
-- computed one, so the timestamp is set here rather than by the caller.
create or replace function set_section_score(
  p_section_id    uuid,
  p_pct           numeric,
  p_collected_pct numeric default null
) returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_pct < 0 or p_pct > 100 then
    raise exception 'computed_pct must be between 0 and 100, got %', p_pct;
  end if;
  update job_book_section
     set computed_pct  = round(p_pct, 2),
         collected_pct = round(greatest(coalesce(p_collected_pct, p_pct), p_pct), 2),
         computed_at   = now()
   where id = p_section_id
     and can_write_job_book(job_book_id);
  if not found then
    raise exception 'section % not found or not writable', p_section_id;
  end if;
end;
$$;

revoke all on function set_section_score(uuid, numeric, numeric) from public;
grant execute on function set_section_score(uuid, numeric, numeric) to authenticated;

-- The client view carries the timestamp too. An operator reading a
-- percentage is entitled to know when it was last worked out.
drop view if exists client_section_v;
create view client_section_v with (security_invoker = true) as
  select id, job_book_id, section_definition_id, status, na_reason,
         approved_at, computed_pct, collected_pct, computed_at
    from job_book_section;

comment on view client_section_v is
  'Client/inspector projection of job_book_section: internal notes and the
   reviewer identities are absent by construction. computed_pct is a cache
   and ships with computed_at so its age is visible.';

grant select on client_section_v to authenticated;


-- ═══════════════════════════════════════════════════════════════════
-- 0009_fix_audit_trigger.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- The audit trigger crashed on every table without a `deleted_at` column.
--
-- Found by running the migrations against a real Postgres for the first
-- time and calling `approve_section()`. The two-person control worked
-- exactly as designed — it refused the submitter and refused a tech — and
-- then a legitimate approver hit:
--
--   ERROR: null value in column "action" of relation "audit_event"
--
-- Two defects, stacked, and the second hid the first.
--
-- 1. The UPDATE branch tested `old.deleted_at`, guarded by a jsonb key
--    check. plpgsql resolves `old.deleted_at` as a field reference on the
--    trigger record regardless of that guard, so on a table with no such
--    column it raises before `v_action` is ever assigned.
--
-- 2. The exception handler then wrote `v_action || '_degraded'`. With
--    `v_action` still null that concatenation is null, and the fallback
--    insert violated the not-null constraint — so the handler meant to
--    keep audit failures from blocking writes became the thing blocking
--    them, and reported a confusing error about a column nobody touched.
--
-- Ten audited tables have no `deleted_at`, and every one of them was
-- unwritable on UPDATE: job_book_section (so no section could ever be
-- approved, marked ready for review, or have its score cached),
-- compliance_flag (no flag could be acknowledged, resolved or dismissed),
-- inspector_grant (no grant could be revoked), inspector_comment,
-- job_assignment, nde_report_line, and the four reference tables.
--
-- The fix reads `deleted_at` out of the jsonb images instead of off the
-- record, which is column-agnostic by construction, and makes the
-- degraded path incapable of producing a null action.
-- ---------------------------------------------------------------------

create or replace function audit_trigger() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_actor   app_user;
  v_book_id uuid;
  v_before  jsonb;
  v_after   jsonb;
  -- Assigned before anything that can raise, so the exception handler
  -- below always has a non-null value to work with. This is the whole
  -- reason the original failure was unreadable.
  v_action  text := lower(tg_op);
begin
  select * into v_actor from current_app_user();

  if tg_op = 'INSERT' then
    v_before := null; v_after := to_jsonb(new); v_action := 'create';
  elsif tg_op = 'UPDATE' then
    v_before := to_jsonb(old); v_after := to_jsonb(new);
    -- Read through the jsonb image rather than the record. `old.deleted_at`
    -- is a field reference plpgsql resolves whatever the guard says, and
    -- ten audited tables do not have that column. A soft delete stays a
    -- distinct, separately-queryable action wherever the column exists.
    v_action := case
      when v_before ? 'deleted_at'
       and v_before ->> 'deleted_at' is null
       and v_after  ->> 'deleted_at' is not null then 'soft_delete'
      else 'update' end;
  else
    v_before := to_jsonb(old); v_after := null; v_action := 'hard_delete';
  end if;

  -- Pull the owning book id from whichever column carries it.
  v_book_id := coalesce(
    (v_after ->> 'job_book_id')::uuid,
    (v_before ->> 'job_book_id')::uuid,
    case when tg_table_name = 'job_book'
         then coalesce((v_after ->> 'id')::uuid, (v_before ->> 'id')::uuid) end
  );

  insert into audit_event (
    actor_id, actor_email, actor_role, job_book_id,
    entity_type, entity_id, action, before_json, after_json,
    ip_address, user_agent
  ) values (
    v_actor.id, v_actor.email, v_actor.role, v_book_id,
    tg_table_name,
    coalesce((v_after ->> 'id')::uuid, (v_before ->> 'id')::uuid),
    v_action, v_before, v_after,
    nullif(current_setting('request.headers', true)::jsonb ->> 'x-forwarded-for','')::inet,
    current_setting('request.headers', true)::jsonb ->> 'user-agent'
  );

  return coalesce(new, old);
exception when others then
  -- Never let audit-context extraction (e.g. a malformed header) block the
  -- write path, but never silently drop the event either. `coalesce` is
  -- belt and braces now that v_action is initialised at declaration: this
  -- insert must not be capable of failing, because it is the last line of
  -- defence and its failure takes the caller's transaction with it.
  insert into audit_event (entity_type, entity_id, action, before_json, after_json)
  values (tg_table_name, coalesce((v_after->>'id')::uuid,(v_before->>'id')::uuid),
          coalesce(v_action, lower(tg_op), 'unknown') || '_degraded', v_before, v_after);
  return coalesce(new, old);
end;
$$;


-- ═══════════════════════════════════════════════════════════════════
-- 0010_document_storage.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- The storage bucket that holds the actual files.
--
-- Until now a document row recorded a hash, a size and a path, and the PDF
-- itself went nowhere. This creates the bucket the upload path writes to
-- and puts the same access rules on the objects that already govern the
-- rows — because a job book's files ARE the confidential material, and a
-- bucket left readable would make every RLS policy in 0003 decorative.
--
-- The bucket is private. There is no permanent public URL for any document
-- in this system; `signDocumentUrl` in `lib/supabase/storage.ts` mints a
-- two-minute signed URL and writes an audit row before it hands it over,
-- so a file that was accessed is a file whose access was recorded.
--
-- Object paths are `<job_book_id>/<section_number>/<sha256>`. The first
-- segment is what these policies read, so the question "may this person
-- touch this object" reduces to the question already answered for the
-- book — `can_read_job_book` and `can_write_job_book`, the same two
-- functions, not a second copy of the rule that could drift from the first.
-- ---------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit)
values ('job-book-documents', 'job-book-documents', false, 104857600)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit;

-- The leading path segment, as a uuid, or null when the path is not shaped
-- the way this application writes them.
create or replace function storage_object_book_id(p_name text)
returns uuid language sql immutable as $$
  select case
    when split_part(p_name, '/', 1) ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    then split_part(p_name, '/', 1)::uuid
  end
$$;

drop policy if exists job_book_documents_read on storage.objects;
create policy job_book_documents_read on storage.objects for select
  using (
    bucket_id = 'job-book-documents'
    and storage_object_book_id(name) is not null
    and can_read_job_book(storage_object_book_id(name))
  );

-- Upload and overwrite are both writes. Overwrite matters because the
-- upload path is content-addressed and re-uploading identical bytes is a
-- legitimate retry.
drop policy if exists job_book_documents_insert on storage.objects;
create policy job_book_documents_insert on storage.objects for insert
  with check (
    bucket_id = 'job-book-documents'
    and storage_object_book_id(name) is not null
    and can_write_job_book(storage_object_book_id(name))
  );

drop policy if exists job_book_documents_update on storage.objects;
create policy job_book_documents_update on storage.objects for update
  using (
    bucket_id = 'job-book-documents'
    and storage_object_book_id(name) is not null
    and can_write_job_book(storage_object_book_id(name))
  );

-- Deleting an object is how the upload path cleans up after a failed row
-- insert, so it is permitted — but a document is removed from a book by
-- soft-deleting its row, which leaves the audit trail intact. Hard-deleting
-- the object is not how you withdraw a document.
drop policy if exists job_book_documents_delete on storage.objects;
create policy job_book_documents_delete on storage.objects for delete
  using (
    bucket_id = 'job-book-documents'
    and storage_object_book_id(name) is not null
    and can_write_job_book(storage_object_book_id(name))
  );


-- ═══════════════════════════════════════════════════════════════════
-- 0011_account_linking.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- Connecting a signed-in account to its app_user row.
--
-- Every security predicate in this schema starts from `app_user`:
-- current_app_role(), current_app_user_id(), can_read_job_book(). A person
-- who authenticates but has no app_user row resolves to no role and no
-- org, so RLS shows them nothing — correct, but it meant that on a fresh
-- deployment the first person to sign in bounced between the sign-in page
-- and a middleware redirect forever. Nobody could get in at all.
--
-- The link is by email, and it is an ALLOWLIST rather than a sign-up.
-- A row in `app_user` is an invitation created by an admin, carrying the
-- role and, for a client user, the operator they belong to. Authenticating
-- with an email nobody has invited creates nothing and grants nothing,
-- which is the property that matters: this application holds one
-- operator's construction records next to another's, and self-service
-- sign-up would make "who are you" a question the visitor answers.
-- ---------------------------------------------------------------------

create or replace function link_auth_user() returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  -- Claim the invitation matching this address, if there is one, and only
  -- if it is unclaimed. `auth_user_id is null` makes this idempotent and
  -- stops a second account taking over an existing person's row.
  update app_user
     set auth_user_id = new.id
   where lower(email) = lower(new.email)
     and auth_user_id is null
     and deleted_at is null;

  -- No match is not an error. The account exists in Supabase Auth and
  -- resolves to no role, which every policy already handles by showing
  -- nothing.
  return new;
end $$;

drop trigger if exists link_auth_user_on_signup on auth.users;
create trigger link_auth_user_on_signup
  after insert on auth.users
  for each row execute function link_auth_user();

-- An invitation created after the person already authenticated — the
-- ordinary case, since someone usually tries to sign in before anyone has
-- set them up — links on insert rather than waiting for a second sign-up
-- that will never come.
create or replace function link_app_user_to_auth() returns trigger
language plpgsql security definer set search_path = public
as $$
declare v_auth uuid;
begin
  if new.auth_user_id is null then
    select id into v_auth from auth.users where lower(email) = lower(new.email) limit 1;
    new.auth_user_id := v_auth;
  end if;
  return new;
end $$;

drop trigger if exists link_app_user_on_insert on app_user;
create trigger link_app_user_on_insert
  before insert on app_user
  for each row execute function link_app_user_to_auth();

-- ---------------------------------------------------------------------
-- Inviting people.
--
-- Creating an app_user row is granting access, so it is an admin action
-- and goes through a function that says so, rather than through a table
-- policy that would have to re-state the same rule.
-- ---------------------------------------------------------------------
create or replace function invite_user(
  p_email     citext,
  p_full_name text,
  p_role      user_role,
  p_client_org_id uuid default null
) returns app_user
language plpgsql security definer set search_path = public
as $$
declare v_actor app_user; v_new app_user;
begin
  select * into v_actor from current_app_user();
  if v_actor.id is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if v_actor.role <> 'fortress_admin' then
    raise exception 'only a Fortress Admin may invite a user' using errcode = '42501';
  end if;

  -- The same constraint the table carries, raised here as a sentence: a
  -- client user without an org would see every operator's books, and a
  -- Fortress user with one would be filtered down to a single client.
  if p_role = 'client_user' and p_client_org_id is null then
    raise exception 'a client user must belong to an operator' using errcode = '23514';
  end if;
  if p_role <> 'client_user' and p_client_org_id is not null then
    raise exception 'only a client user may belong to an operator' using errcode = '23514';
  end if;

  insert into app_user (email, full_name, role, client_org_id)
  values (p_email, p_full_name, p_role, p_client_org_id)
  returning * into v_new;
  return v_new;
end $$;

revoke all on function invite_user(citext, text, user_role, uuid) from public;
grant execute on function invite_user(citext, text, user_role, uuid) to authenticated;

comment on function invite_user is
  'Grant a person access. Admin-only. The app_user row is the invitation; '
  'it links to their account by email the moment either side appears.';


-- ═══════════════════════════════════════════════════════════════════
-- 0012_lock_down_rpc_surface.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- Close the RPC surface, and fix a mutable search_path.
--
-- Both found by Supabase's own database linter once the schema was live,
-- which is the argument for running `get_advisors` after any DDL: neither
-- of these is visible from the migration file alone.
--
-- 1. `storage_object_book_id` was created without `set search_path`. It is
--    called from the storage object policies, so a caller able to
--    manipulate the search path could shadow what it resolves — inside the
--    function that decides which job book a file belongs to. Every other
--    function in this schema pins it; this one was an oversight.
--
-- 2. Postgres grants EXECUTE on new functions to PUBLIC, and Supabase
--    exposes everything in `public` at `/rest/v1/rpc/<name>`. So all
--    nineteen functions here were callable by `anon` — an unauthenticated
--    caller off the open internet. The definer functions each begin by
--    resolving `current_app_user()`, which is null for anon, so they raise
--    rather than act; but "it fails safe" is a weaker claim than "it
--    cannot be called", and `log_document_access` in particular would have
--    let an anonymous caller write rows into an append-only audit log that
--    nobody — by design — can then delete.
--
-- The read-only predicates (`can_read_job_book`, `is_fortress_staff`, the
-- `current_*` family) deliberately keep their grant to `authenticated`:
-- RLS policy expressions are evaluated as the querying role, so revoking
-- EXECUTE there would break every policy that calls them. They return
-- false or null for an unauthenticated caller and leak nothing.
-- ---------------------------------------------------------------------

create or replace function storage_object_book_id(p_name text)
returns uuid language sql immutable
set search_path = public
as $$
  select case
    when split_part(p_name, '/', 1) ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    then split_part(p_name, '/', 1)::uuid
  end
$$;

-- Mutating functions: never reachable without a session.
revoke execute on function approve_section(uuid) from public, anon;
revoke execute on function create_job_book(uuid, book_type, text, jsonb, jsonb, jsonb) from public, anon;
revoke execute on function invite_user(citext, text, user_role, uuid) from public, anon;
revoke execute on function set_section_score(uuid, numeric, numeric) from public, anon;
revoke execute on function log_document_access(uuid, text) from public, anon;

grant execute on function approve_section(uuid) to authenticated;
grant execute on function create_job_book(uuid, book_type, text, jsonb, jsonb, jsonb) to authenticated;
grant execute on function invite_user(citext, text, user_role, uuid) to authenticated;
grant execute on function set_section_score(uuid, numeric, numeric) to authenticated;
grant execute on function log_document_access(uuid, text) to authenticated;

-- Trigger functions are invoked by the trigger, never by a caller. A
-- trigger runs its function regardless of the caller's EXECUTE privilege,
-- so revoking from everyone removes the RPC endpoint and changes nothing
-- about how auditing or account linking actually work.
revoke execute on function audit_trigger() from public, anon, authenticated;
revoke execute on function link_auth_user() from public, anon, authenticated;
revoke execute on function link_app_user_to_auth() from public, anon, authenticated;


-- ═══════════════════════════════════════════════════════════════════
-- 0013_allowlist_at_signup.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- The allowlist belongs in the database, not in a dashboard toggle.
--
-- 0011 made `app_user` an invitation list and linked it to an auth account
-- by email. What it did not account for is that a first sign-in has to
-- CREATE that auth account — and the application asked for the link with
-- `shouldCreateUser: false` while the project had signups disabled. Two
-- locks on the same door, and the invitation on the other side of it.
-- Result: zero auth accounts, and no path to a first one. Not even for the
-- admin who set the system up.
--
-- Turning signups back on would fix the deadlock and lose the allowlist,
-- which is not a trade worth making: this holds one operator's records
-- next to another's.
--
-- So the rule moves here. Signups are enabled at the project level, and
-- Postgres refuses to create an account for an address nobody invited.
-- That is better than the toggle in both directions — it survives someone
-- flipping a dashboard setting, and it lets an invited person in.
-- ---------------------------------------------------------------------

create or replace function enforce_signup_allowlist() returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if exists (
    select 1 from app_user
     where lower(email) = lower(new.email)
       and deleted_at is null
  ) then
    return new;
  end if;

  -- Deliberately the same wording the sign-in screen shows, so a person
  -- who reaches it by a different route reads the same sentence.
  raise exception
    'That address has not been invited to this system. Ask a Fortress admin to add you.'
    using errcode = '42501';
end $$;

comment on function enforce_signup_allowlist is
  'Refuses an auth account for an address with no app_user invitation. The '
  'allowlist is enforced here rather than by the project''s signup toggle, '
  'so it survives that toggle being changed.';

drop trigger if exists enforce_signup_allowlist_on_auth_users on auth.users;
create trigger enforce_signup_allowlist_on_auth_users
  before insert on auth.users
  for each row execute function enforce_signup_allowlist();

revoke execute on function enforce_signup_allowlist() from public, anon, authenticated;


-- ═══════════════════════════════════════════════════════════════════
-- 0014_program_alignment.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- Alignment with FDS-JBMP-001, first pass.
--
-- Three defects against Fortress's own program, found by reading the app
-- against it section by section.
--
-- 1. GOVERNING DOCUMENTS WERE A SECTION TITLE, NOT A FIELD.
--
--    Four section titles carried "Noble Energy" and "(Noble Template)"
--    while the specification actually on file had moved to Chevron at a
--    later revision. §3 of the program names that exact condition "a
--    finding waiting to happen", and Appendix A gives the titles
--    operator-neutral.
--
--    Retitling alone would lose information, because the Noble document IS
--    the one in force until the client says otherwise. So which document
--    governs becomes a recorded field, confirmed with the client at Gate 0
--    and re-confirmed on any revision — which is what §3 asks for and what
--    form F01 section 2 collects.
--
-- 2. A PRESSURE TEST CARRIED ONE CERTIFICATE WHERE THE PROGRAM REQUIRES
--    THREE.
--
--    §11.1 makes it a Critical finding to accept a test "without gauge,
--    recorder and pressure safety valve certificates valid on the test
--    date", and Appendix A §17 says the same. The table held only
--    `recorder_cert_id`, so two thirds of that check could not be made —
--    and the baseline review found 13 of 21 facility test packages holding
--    certificates but no result document, which is the neighbouring
--    failure.
-- ---------------------------------------------------------------------

alter table job_book
  -- The client checklist and piping specification actually in force, by
  -- name and revision. Free text because they are the client's documents,
  -- named as the client names them.
  add column client_checklist_reference   text,
  add column client_checklist_revision    text,
  add column piping_spec_reference        text,
  add column piping_spec_revision         text,
  -- Gate 0 requires these confirmed CURRENT with the client, not merely
  -- recorded. A date nobody set means nobody asked.
  add column governing_docs_confirmed_at  date,
  add column governing_docs_confirmed_by  uuid references app_user(id);

comment on column job_book.piping_spec_reference is
  'The piping specification in force for this job, as the client names it '
  '(e.g. "Noble Energy Piping Specification" or '
  '"DJBU-GL-RBU-PIP-SPC-0001"). Recorded here rather than in a section '
  'title so it can be changed when the client changes it.';

comment on column job_book.governing_docs_confirmed_at is
  'When the checklist and specification revisions were last confirmed '
  'current with the client. FDS-JBMP-001 §3 and Gate 0.';

-- ---------------------------------------------------------------------
-- A pressure test needs three instruments certified on the test date.
-- ---------------------------------------------------------------------
alter table pressure_test
  add column gauge_serial     text,
  add column gauge_cert_id    uuid references certificate(id),
  add column psv_serial       text,
  add column psv_cert_id      uuid references certificate(id),
  -- §17 acceptance criteria: hold data, not just a pass/fail.
  add column start_pressure_psi  numeric(10,2),
  add column end_pressure_psi    numeric(10,2),
  add column ambient_temp_f      numeric(6,2),
  -- "No test present as certificates only" — Appendix A §17. A package
  -- holding instrument certificates and no result document is the single
  -- most common defect the baseline review found in section 17.
  add column result_document_id uuid references document(id);

comment on column pressure_test.gauge_cert_id is
  'Gauge calibration. FDS-JBMP-001 §11.1 makes a test accepted without '
  'gauge, recorder AND PSV certificates valid on the test date a Critical '
  'finding; the table previously held only the recorder.';

comment on column pressure_test.result_document_id is
  'The result document. Appendix A §17: "No test present as certificates '
  'only." The baseline review found 13 of 21 facility packages in exactly '
  'that state.';

-- 'pressure_recorder' already exists in cert_subject_type and covers all
-- three instruments; the subject_id points at the test and the cert_type
-- names which instrument it certifies.


-- ═══════════════════════════════════════════════════════════════════
-- 0015_gates_and_custodian.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- FDS-JBMP-001 §5, §6, §7 — the governance spine.
--
-- Until now the app measured a job book and said nothing about who owned
-- it or whether it was allowed to advance. The program's force comes from
-- exactly those two things, and §2 names their absence as root causes 1
-- and 2 of the baseline review:
--
--   "No single named person owned a job book. Ownership was implied by
--    proximity to the work."
--
-- So: a book gets a Custodian, and it gets gates.
--
-- WHAT A GATE REVIEW IS. §7: "A gate review is a documented decision, not
-- a conversation." Three outcomes — Pass, Conditional Pass with a dated
-- action list, Fail. The rule that gives gates their force is the ten-day
-- ceiling on a Conditional Pass, issuable once per gate, after which it
-- becomes a Fail and escalates to the VP the same day.
--
-- WHY THE CRITERIA ARE SNAPSHOTTED. A gate decision asserts something
-- about the book ON THE DAY IT WAS TAKEN. Re-deriving those criteria later
-- would answer a different question, and would quietly rewrite history
-- every time a record changed. The evaluation travels with the decision,
-- frozen, the same reasoning that put `computed_pct` on the section row.
--
-- WHAT THIS MIGRATION DOES NOT DO. It does not let the database decide a
-- gate. Several criteria (peer-audit score, client confirmation, lessons
-- learned held) are human attestations by construction, and several others
-- depend on the Tier 1/2/3 audit model that does not exist yet. The domain
-- engine reports those as INDETERMINATE rather than met, and a chair who
-- passes a gate on an indeterminate criterion has to say so in writing.
-- Silence is never scored as compliance.
-- ---------------------------------------------------------------------

create type gate_id        as enum ('G0','G1','G2','G3','G4','G5');
create type gate_outcome   as enum ('pass','conditional_pass','fail');

-- §5.1 / FDS-JBMP-004. A Custodian holds JB-2 or above; a Peer Auditor
-- holds JB-3. Competency is a property of the person, not of the book, and
-- gate criteria read it.
create type competency_level as enum ('JB-1','JB-2','JB-3','JB-4');

alter table app_user
  add column competency_level competency_level,
  add column competency_granted_at date,
  add column competency_granted_by uuid references app_user(id);

comment on column app_user.competency_level is
  'FDS-JBMP-004 competency. JB-2 or above may hold Custodian; JB-3 or above
   may perform a Tier 2 peer audit. Null means not yet assessed, which is
   not the same as JB-1 and must never be read as qualified.';

-- ---------------------------------------------------------------------
-- §5: "Every job book has exactly one Custodian." Named at Gate 0, in
-- writing, and appearing on every gate review and every submission.
-- ---------------------------------------------------------------------
alter table job_book
  add column custodian_id          uuid references app_user(id),
  add column custodian_assigned_at timestamptz,
  add column custodian_assigned_by uuid references app_user(id),
  -- §6.2. The curve is agreed at Gate 0 against the construction schedule
  -- and defaults to the program's milestones. Stored as the book's own
  -- copy because a later revision of the program must not silently move
  -- the bar a running book is measured against.
  add column planned_curve         jsonb,
  -- Set once a gate is decided; kept denormalised so a book list can show
  -- where every book stands without replaying every review.
  add column current_gate          gate_id,
  add column current_gate_at       timestamptz;

-- §7 Gate 0: "Section expected by dates set against the construction
-- schedule." The section already declares HOW MUCH it will hold
-- (expected_count, 0005); this declares WHEN. Without it a book can be
-- behind and look merely incomplete.
alter table job_book_section
  add column expected_by date;

comment on column job_book_section.expected_by is
  'FDS-JBMP-001 §7 Gate 0. The date this section is expected to be complete,
   set from the construction schedule. Null means no date was set, which is
   a Gate 0 criterion unmet, not a section with no deadline.';

-- Having a curve is not the same as having agreed one. Gate 0 checks the
-- agreement.
alter table job_book
  add column planned_curve_agreed_at date,
  add column planned_curve_agreed_by uuid references app_user(id);

comment on column job_book.planned_curve is
  'FDS-JBMP-001 §6.2 planned completion curve: an array of
   {milestone, minimumPct} agreed at Gate 0. Actual weighted completion is
   reported against it weekly.';

-- The program default, applied to books that have not set their own. A
-- book still has to AGREE it at Gate 0 — having a curve is not the same as
-- having agreed one, so Gate 0 checks the agreement, not the column.
alter table job_book alter column planned_curve set default
  '[{"milestone":"gate_0_passed","minimumPct":8},
    {"milestone":"construction_25","minimumPct":25},
    {"milestone":"construction_50","minimumPct":50},
    {"milestone":"mechanical_completion","minimumPct":85},
    {"milestone":"gate_4_entry","minimumPct":98},
    {"milestone":"submission","minimumPct":100}]'::jsonb;

-- Books that already exist adopt the program default.
update job_book
   set planned_curve = '[{"milestone":"gate_0_passed","minimumPct":8},
    {"milestone":"construction_25","minimumPct":25},
    {"milestone":"construction_50","minimumPct":50},
    {"milestone":"mechanical_completion","minimumPct":85},
    {"milestone":"gate_4_entry","minimumPct":98},
    {"milestone":"submission","minimumPct":100}]'::jsonb
 where planned_curve is null;

-- ---------------------------------------------------------------------
-- The decision record. Form FDS-JB-F06.
-- ---------------------------------------------------------------------
create table gate_review (
  id                uuid primary key default gen_random_uuid(),
  job_book_id       uuid not null references job_book(id) on delete cascade,
  gate              gate_id not null,
  -- A gate may be reviewed more than once: a Fail is re-reviewed, and a
  -- Conditional Pass that lapses is re-decided. Attempts are numbered so
  -- "failed the same gate twice" (§7) is a query, not an interpretation.
  attempt           integer not null default 1,
  outcome           gate_outcome not null,

  -- §7: chaired by the QA/QC Manager, attended by the Custodian and the
  -- Project Manager. All three are recorded because the program makes the
  -- gate a project milestone co-signed by the PM, not a QA/QC formality.
  chaired_by        uuid not null references app_user(id),
  custodian_id      uuid references app_user(id),
  project_manager_id uuid references app_user(id),
  decided_at        timestamptz not null default now(),

  -- The criteria as they stood when the decision was taken. Frozen.
  criteria_snapshot jsonb not null,
  -- Weighted completion at the moment of decision, for the §6.2 curve.
  completion_pct    numeric(5,2),

  -- Conditional Pass only. §7 caps the window at ten calendar days.
  conditional_due_at date,
  cleared_at        timestamptz,
  cleared_by        uuid references app_user(id),

  -- A chair who passes a gate while a criterion is unmet or unevaluable
  -- has to say why, in writing, on the record.
  override_note     text,
  notes             text,

  created_at        timestamptz not null default now(),

  unique (job_book_id, gate, attempt),

  -- §7: "A Conditional Pass carries a maximum of ten calendar days."
  constraint conditional_has_due_date check (
    (outcome <> 'conditional_pass') or conditional_due_at is not null
  ),
  constraint conditional_window_is_ten_days check (
    conditional_due_at is null
    or conditional_due_at <= (decided_at at time zone 'UTC')::date + 10
  ),
  -- A clean Pass carries no dated action list and no clearing step.
  constraint pass_carries_no_conditions check (
    outcome <> 'pass' or (conditional_due_at is null and cleared_at is null)
  ),
  constraint cleared_is_attributed check (
    cleared_at is null or cleared_by is not null
  ),
  -- Two-person control, same principle as section approval: the chair may
  -- not be the Custodian of the book being gated.
  constraint chair_is_not_custodian check (
    custodian_id is null or chaired_by <> custodian_id
  )
);

create index gate_review_book_idx on gate_review (job_book_id, gate, attempt desc);

-- §7: a Conditional Pass "may be issued once per gate".
create unique index gate_review_one_conditional_per_gate
  on gate_review (job_book_id, gate)
  where outcome = 'conditional_pass';

comment on table gate_review is
  'FDS-JBMP-001 §7 gate review, form FDS-JB-F06. Append-mostly: a row is
   written when the decision is taken and afterwards only its clearing
   fields move. Every change is captured by the audit trigger.';

-- ---------------------------------------------------------------------
-- The dated action list that a Conditional Pass carries. §7 gives the
-- list its teeth: items are dated, owned, and closed with evidence — the
-- same shape as an NCR, because that is what they are.
-- ---------------------------------------------------------------------
create table gate_condition (
  id              uuid primary key default gen_random_uuid(),
  gate_review_id  uuid not null references gate_review(id) on delete cascade,
  criterion_id    text,                 -- which criterion it answers, if any
  description     text not null,
  owner_id        uuid not null references app_user(id),
  due_at          date not null,
  closed_at       timestamptz,
  closed_by       uuid references app_user(id),
  closure_note    text,
  created_at      timestamptz not null default now(),

  -- §11: findings "are not closed verbally".
  constraint closure_is_attributed check (
    closed_at is null or (closed_by is not null and closure_note is not null)
  )
);

create index gate_condition_review_idx on gate_condition (gate_review_id);

-- ---------------------------------------------------------------------
-- §11.5 — an NCR carries an owner and a due date, and ages against it.
-- Gate 1 reads "zero open NCRs past due date", which the flag table could
-- not answer: it had an assignee but no date to be late against.
-- ---------------------------------------------------------------------
alter table compliance_flag
  add column due_at        date,
  add column escalated_at  timestamptz;

comment on column compliance_flag.due_at is
  'FDS-JBMP-001 §11.5. An NCR with no due date cannot be past due, so gate
   criteria treat a dateless open Critical or Major finding as unmet rather
   than as compliant.';

-- ---------------------------------------------------------------------
-- Advancing the book. The gate decides the phase; nothing else may.
-- ---------------------------------------------------------------------
create or replace function record_gate_review(
  p_book              uuid,
  p_gate              gate_id,
  p_outcome           gate_outcome,
  p_criteria          jsonb,
  p_completion_pct    numeric default null,
  p_custodian         uuid default null,
  p_project_manager   uuid default null,
  p_conditional_due   date default null,
  p_override_note     text default null,
  p_notes             text default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_chair    uuid := current_app_user_id();
  v_attempt  integer;
  v_id       uuid;
  v_unmet    integer;
begin
  if v_chair is null then
    raise exception 'no authenticated app user';
  end if;

  -- §5.1: "The only role authorized to submit a job book to a client" also
  -- chairs gate reviews. A tech cannot pass their own book forward.
  if not is_manager_or_admin() then
    raise exception 'only a QA/QC manager or admin may chair a gate review';
  end if;

  if not can_write_job_book(p_book) then
    raise exception 'not authorised for this job book';
  end if;

  -- A Pass or Conditional Pass taken while criteria are unmet or could not
  -- be evaluated is allowed — the chair is the decision-maker, not the
  -- app — but it must be explained. An unexplained override is refused.
  select count(*) into v_unmet
    from jsonb_array_elements(p_criteria) c
   where c->>'state' in ('not_met','indeterminate');

  if p_outcome <> 'fail' and v_unmet > 0
     and coalesce(length(trim(p_override_note)), 0) = 0 then
    raise exception
      'gate % has % unmet or unevaluable criteria; an override note is required',
      p_gate, v_unmet;
  end if;

  select coalesce(max(attempt), 0) + 1 into v_attempt
    from gate_review where job_book_id = p_book and gate = p_gate;

  insert into gate_review (
    job_book_id, gate, attempt, outcome, chaired_by, custodian_id,
    project_manager_id, criteria_snapshot, completion_pct,
    conditional_due_at, override_note, notes
  ) values (
    p_book, p_gate, v_attempt, p_outcome, v_chair,
    coalesce(p_custodian, (select custodian_id from job_book where id = p_book)),
    p_project_manager, p_criteria, p_completion_pct,
    p_conditional_due, nullif(trim(p_override_note), ''), nullif(trim(p_notes), '')
  ) returning id into v_id;

  -- The book advances only on a clean Pass. A Conditional Pass is a
  -- promise, not an advance: §7 makes it lapse into a Fail if the window
  -- closes uncleared, and a book that had already moved on would then be
  -- standing past a gate it did not pass.
  if p_outcome = 'pass' then
    update job_book
       set current_gate = p_gate, current_gate_at = now()
     where id = p_book;
  end if;

  return v_id;
end $$;

revoke execute on function record_gate_review(
  uuid, gate_id, gate_outcome, jsonb, numeric, uuid, uuid, date, text, text
) from anon;

-- ---------------------------------------------------------------------
-- Assigning the Custodian. §5: one book, one Custodian, JB-2 or above,
-- named in writing by the QA/QC Manager.
-- ---------------------------------------------------------------------
create or replace function assign_custodian(p_book uuid, p_user uuid)
returns void
language plpgsql security definer set search_path = public as $$
declare v_level competency_level;
begin
  if not is_manager_or_admin() then
    raise exception 'only a QA/QC manager or admin may assign a Custodian';
  end if;
  if not can_write_job_book(p_book) then
    raise exception 'not authorised for this job book';
  end if;

  select competency_level into v_level from app_user
   where id = p_user and deleted_at is null and is_active;

  if not found then
    raise exception 'no such active user';
  end if;

  -- Null is "not assessed", and not assessed is not qualified.
  if v_level is null or v_level = 'JB-1' then
    raise exception
      'Custodian requires competency JB-2 or above (FDS-JBMP-001 §5.1); user holds %',
      coalesce(v_level::text, 'no assessed level');
  end if;

  update job_book
     set custodian_id = p_user,
         custodian_assigned_at = now(),
         custodian_assigned_by = current_app_user_id()
   where id = p_book;
end $$;

revoke execute on function assign_custodian(uuid, uuid) from anon;

-- ---------------------------------------------------------------------
-- RLS. Gate reviews are Fortress-internal governance: a client sees the
-- book, not the minutes of the meeting where Fortress decided whether to
-- let it advance.
-- ---------------------------------------------------------------------
alter table gate_review enable row level security;
alter table gate_review force row level security;
alter table gate_condition enable row level security;
alter table gate_condition force row level security;

create policy gate_review_read on gate_review for select using (
  is_fortress_staff() and can_read_job_book(job_book_id)
);
create policy gate_review_write on gate_review for all
  using (is_manager_or_admin() and can_write_job_book(job_book_id))
  with check (is_manager_or_admin() and can_write_job_book(job_book_id));

create policy gate_condition_read on gate_condition for select using (
  exists (select 1 from gate_review r
           where r.id = gate_review_id
             and is_fortress_staff() and can_read_job_book(r.job_book_id))
);
-- A condition is closed by the person who owns it, which is usually the
-- Custodian, so writing here is open to any Fortress writer on the book.
create policy gate_condition_write on gate_condition for all
  using (exists (select 1 from gate_review r
                  where r.id = gate_review_id and can_write_job_book(r.job_book_id)))
  with check (exists (select 1 from gate_review r
                       where r.id = gate_review_id and can_write_job_book(r.job_book_id)));

-- ---------------------------------------------------------------------
-- Audit. Both new tables join the append-only trail.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['gate_review','gate_condition'] loop
    execute format(
      'create trigger %I_audit after insert or update or delete on %I
         for each row execute function audit_trigger()', t, t);
  end loop;
end $$;


-- ═══════════════════════════════════════════════════════════════════
-- 0016_close_gate_rpc_grant.sql
-- ═══════════════════════════════════════════════════════════════════

-- ---------------------------------------------------------------------
-- The two functions 0015 added were left reachable by anon.
--
-- 0012 established the pattern and stated the reason: Postgres grants
-- EXECUTE on a new function to PUBLIC, and `anon` inherits from PUBLIC, so
-- revoking from `anon` alone removes nothing. Every mutating function has
-- to be revoked `from public, anon` and granted back to `authenticated`.
--
-- 0015 revoked from `anon` only. Both functions refuse an unauthenticated
-- caller on their own — each begins by resolving `current_app_user_id()`,
-- which is null for anon, and raises — but 0012's own words apply: "it
-- fails safe" is a weaker claim than "it cannot be called". Caught by the
-- Supabase security advisor after 0015 reached the live project.
-- ---------------------------------------------------------------------

revoke execute on function record_gate_review(
  uuid, gate_id, gate_outcome, jsonb, numeric, uuid, uuid, date, text, text
) from public, anon;
revoke execute on function assign_custodian(uuid, uuid) from public, anon;

grant execute on function record_gate_review(
  uuid, gate_id, gate_outcome, jsonb, numeric, uuid, uuid, date, text, text
) to authenticated;
grant execute on function assign_custodian(uuid, uuid) to authenticated;


